update public.challenge_plans set days = $plan$[{"t":"Toma 8 vasos de agua. Un vaso de agua apenas te levantas, antes del café.","type":"habito","target":8},{"t":"Toma 8 vasos de agua. Deja una botella llena a la vista en tu escritorio o mesa.","type":"habito","target":8},{"t":"Toma 8 vasos de agua. Un vaso antes de cada comida: también te ayuda a comer con calma.","type":"habito","target":8},{"t":"Toma 8 vasos de agua. Si te aburre el agua sola, ponle limón, pepino o hierbabuena.","type":"habito","target":8},{"t":"Toma 8 vasos de agua. Un vaso al llegar del gym o después de caminar.","type":"habito","target":8},{"t":"Toma 8 vasos de agua. Pon una alarma cada 2 horas y toma medio vaso en cada una.","type":"habito","target":8},{"t":"Toma 8 vasos de agua. Revisa el color de tu orina: amarillo claro es buena señal.","type":"habito","target":8},{"t":"Toma 8 vasos de agua. Cambia el refresco o el jugo de hoy por agua fría con fruta.","type":"habito","target":8},{"t":"Toma 8 vasos de agua. Si entrenas hoy, suma 1 o 2 vasos más.","type":"habito","target":8},{"t":"Toma 8 vasos de agua. Prepara 2 botellas de 1 litro en la mañana y termínalas antes de la noche.","type":"habito","target":8},{"t":"Toma 8 vasos de agua. Toma un vaso cuando sientas hambre entre comidas y espera 10 minutos.","type":"habito","target":8},{"t":"Toma 8 vasos de agua. Agua de coco o un té sin azúcar también cuentan.","type":"habito","target":8},{"t":"Toma 8 vasos de agua. Lleva una botella en el carro o en la mochila.","type":"habito","target":8},{"t":"Toma 8 vasos de agua. Día final: compara tu energía y tu hambre con el día 1.","type":"habito","target":8}]$plan$::jsonb, updated_at = now() where slug in (select slug from public.challenges_catalog where slug = 'agua-21' and price_usd = 0 and title in ('Hidratado', 'Hidratado 21 días'));
