-- Un reto gratis publicado dura como máximo 15 días (los ocultos o archivados quedan como estaban).
do $$ begin
  alter table public.challenges_catalog drop constraint if exists challenges_catalog_free_days_check;
  alter table public.challenges_catalog add constraint challenges_catalog_free_days_check check (
    not (status = 'publicado' and price_usd = 0 and coalesce(kind, 'reto') = 'reto' and days > 15)
  );
end $$;

-- Comprobación: los retos gratis publicados.
select slug, title, days, status from public.challenges_catalog where price_usd = 0 and coalesce(kind, 'reto') = 'reto' order by status, sort;
